query:
*[_type=="blogPost" && references(*[_type=="blogTag" && slug.current=="technical"]._id) && isHidden != true] | order(body.publishedAt desc) [0...100] {
  "slug": body.slug.current, "title": body.title, "publishedAt": body.publishedAt,
  "description": body.description, "image": body.thumbnail.asset->url,
  "authors": body.postAuthors[]->name
}
